FUNCTION_BLOCK FB
VAR_INPUT
    estop           : BOOL;
    opeMode         : BOOL;
    valveAStart     : BOOL;
    valveBStart     : BOOL;
    valveCStart     : BOOL;
    valveDStart     : BOOL;
    mixMotorStart   : BOOL;
    autoStart       : BOOL;
    processMode     : BOOL;
    levelSensor     : INT;
    mixMotorComplete: BOOL;
END_VAR
VAR_OUTPUT
    valveARun   : BOOL;
    valveBRun   : BOOL;
    valveCRun   : BOOL;
    valveDRun   : BOOL;
    mixMotorRun : BOOL;
END_VAR
VAR
    autoState      : INT;         (* 0=IDLE,1=FILL_A,2=FILL_B,3=FILL_C,4=MIXING,5=DRAIN *)
    prev_autoStart : BOOL;
    prev_estop     : BOOL;
    prev_opeMode   : BOOL;
    prev_valveAStart: BOOL;
    prev_valveBStart: BOOL;
    prev_valveCStart: BOOL;
    prev_valveDStart: BOOL;
    prev_mixMotorStart: BOOL;
    prev_valveARun  : BOOL;
    prev_valveBRun  : BOOL;
    prev_valveCRun  : BOOL;
    prev_valveDRun  : BOOL;
    prev_mixMotorRun: BOOL;
    prev_levelSensor: INT;
    prev_mixMotorComplete: BOOL;
    prev_autoState  : INT;
    startHistoryFlag: BOOL;
END_VAR

    (* --- Rising edge detection helpers --- *)
    VAR risingAutoStart     : BOOL; risingAutoStart     := autoStart      AND NOT prev_autoStart;
    VAR risingValveAStart   : BOOL; risingValveAStart   := valveAStart    AND NOT prev_valveAStart;
    VAR risingValveBStart   : BOOL; risingValveBStart   := valveBStart    AND NOT prev_valveBStart;
    VAR risingValveCStart   : BOOL; risingValveCStart   := valveCStart    AND NOT prev_valveCStart;
    VAR risingValveDStart   : BOOL; risingValveDStart   := valveDStart    AND NOT prev_valveDStart;
    VAR risingMixMotorStart : BOOL; risingMixMotorStart := mixMotorStart  AND NOT prev_mixMotorStart;
    VAR risingMixMotorComplete: BOOL; risingMixMotorComplete := mixMotorComplete AND NOT prev_mixMotorComplete;

    (* --- Start history flag: set on any start signal, stays set --- *)
    IF valveAStart OR valveBStart OR valveCStart OR valveDStart OR
       mixMotorStart OR autoStart THEN
        startHistoryFlag := TRUE;
    END_IF

    (* ================================================================ *)
    (*  S1  Emergency Stop: all equipment off                           *)
    (* ================================================================ *)
    IF NOT estop THEN
        valveARun   := FALSE;
        valveBRun   := FALSE;
        valveCRun   := FALSE;
        valveDRun   := FALSE;
        mixMotorRun := FALSE;
        autoState   := 0;
    (* ================================================================ *)
    (*  Manual Mode                                                     *)
    (* ================================================================ *)
    ELSIF NOT opeMode THEN
        valveARun   := prev_valveARun   XOR risingValveAStart;
        valveBRun   := prev_valveBRun   XOR risingValveBStart;
        valveCRun   := prev_valveCRun   XOR risingValveCStart;
        valveDRun   := prev_valveDRun   XOR risingValveDStart;
        mixMotorRun := prev_mixMotorRun XOR risingMixMotorStart;
        autoState   := 0;
    (* ================================================================ *)
    (*  Automatic Mode                                                  *)
    (* ================================================================ *)
    ELSE
        (* N10-S14: first four scans with no start signal → all off *)
        IF NOT startHistoryFlag THEN
            valveARun   := FALSE;
            valveBRun   := FALSE;
            valveCRun   := FALSE;
            valveDRun   := FALSE;
            mixMotorRun := FALSE;
            autoState   := 0;
        ELSE
            CASE autoState OF
                (* ---- 0: IDLE, wait for autoStart rising edge ---- *)
                0:  valveARun   := FALSE;
                    valveBRun   := FALSE;
                    valveCRun   := FALSE;
                    valveDRun   := FALSE;
                    mixMotorRun := FALSE;
                    IF risingAutoStart THEN
                        autoState := 1;
                    END_IF

                (* ---- 1: FILL A, open A until level >= 50 ---- *)
                1:  valveARun   := (levelSensor < 50);
                    valveBRun   := FALSE;
                    valveCRun   := FALSE;
                    valveDRun   := FALSE;
                    mixMotorRun := FALSE;
                    IF levelSensor >= 50 THEN
                        autoState := 2;
                    END_IF

                (* ---- 2: FILL B, open B until level >= 80 ---- *)
                2:  valveARun   := FALSE;
                    valveBRun   := (levelSensor < 80);
                    valveCRun   := FALSE;
                    valveDRun   := FALSE;
                    mixMotorRun := FALSE;
                    IF levelSensor >= 80 THEN
                        autoState := 3;
                    END_IF

                (* ---- 3: FILL C (processMode=TRUE) or MIX (processMode=FALSE) ---- *)
                3:  IF processMode THEN
                        valveARun   := FALSE;
                        valveBRun   := FALSE;
                        valveCRun   := (levelSensor < 100);
                        valveDRun   := FALSE;
                        mixMotorRun := FALSE;
                        IF levelSensor >= 100 THEN
                            autoState := 4;
                        END_IF
                    ELSE
                        valveARun   := FALSE;
                        valveBRun   := FALSE;
                        valveCRun   := FALSE;
                        valveDRun   := FALSE;
                        mixMotorRun := TRUE;
                        IF risingMixMotorComplete THEN
                            autoState := 5;
                        END_IF
                    END_IF

                (* ---- 4: MIXING, hold until mixMotorComplete rising edge ---- *)
                4:  valveARun   := FALSE;
                    valveBRun   := FALSE;
                    valveCRun   := FALSE;
                    valveDRun   := FALSE;
                    mixMotorRun := TRUE;
                    IF risingMixMotorComplete THEN
                        autoState := 5;
                    END_IF

                (* ---- 5: DRAIN, open D then return to IDLE ---- *)
                5:  valveARun   := FALSE;
                    valveBRun   := FALSE;
                    valveCRun   := FALSE;
                    valveDRun   := TRUE;
                    mixMotorRun := FALSE;
                    autoState   := 0;
            END_CASE
        END_IF
    END_IF

    (* --- Update all previous-value variables for next scan --- *)
    prev_autoStart       := autoStart;
    prev_estop           := estop;
    prev_opeMode         := opeMode;
    prev_valveAStart     := valveAStart;
    prev_valveBStart     := valveBStart;
    prev_valveCStart     := valveCStart;
    prev_valveDStart     := valveDStart;
    prev_mixMotorStart   := mixMotorStart;
    prev_valveARun       := valveARun;
    prev_valveBRun       := valveBRun;
    prev_valveCRun       := valveCRun;
    prev_valveDRun       := valveDRun;
    prev_mixMotorRun     := mixMotorRun;
    prev_levelSensor     := levelSensor;
    prev_mixMotorComplete:= mixMotorComplete;
    prev_autoState       := autoState;
END_FUNCTION_BLOCK

